-- GOVAPARK étape 14 : journal d'audit, justificatifs propriétaires et remboursements.
CREATE TABLE adminAuditLogs (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, actorId BIGINT UNSIGNED NOT NULL, action VARCHAR(100) NOT NULL, targetType VARCHAR(60) NOT NULL, targetId VARCHAR(80) NULL, details TEXT NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX admin_audit_actor_idx (actorId, createdAt), INDEX admin_audit_action_idx (action, createdAt));
CREATE TABLE refundRequests (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, reservationId BIGINT UNSIGNED NOT NULL UNIQUE, requestedBy BIGINT UNSIGNED NOT NULL, reason VARCHAR(1000) NOT NULL, previousStatus VARCHAR(40) NOT NULL DEFAULT 'confirmed', status ENUM('requested','under_review','approved','rejected','processed') NOT NULL DEFAULT 'requested', amountCents INT NOT NULL, providerReference VARCHAR(180) NULL, adminNote TEXT NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX refund_requests_status_idx (status, createdAt));
CREATE TABLE ownerVerificationDocuments (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, userId BIGINT UNSIGNED NOT NULL, fileKey VARCHAR(600) NOT NULL, documentType ENUM('identity','property_proof','company_registration') NOT NULL, originalName VARCHAR(180) NOT NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX owner_verification_docs_user_idx (userId, createdAt));
